import{_ as l,C as i,o as e,c as p,a2 as t,E as n}from"./chunks/framework.BnBoz4Zl.js";const d="/anjian-workbuddy-bluebook-site/assets/006_synthetic_dashboard_demo.8ySIQ1w9.svg",B=JSON.parse('{"title":"第 24 章 备份、校验与恢复演练","description":"备份的价值由恢复结果决定。看到“复制完成”或“同步成功”只能说明流程执行过；只有校验通过，并且资产已经在新的空目录中恢复且能够继续使用，才能证明恢复链路有效。 本章提供通用治理方法，不指定公司正式存储系统、保留周期或恢复责任。具体位置、权限、保密要求和恢复目标应由信息化、安全、业务和资料责任人共同确认。","frontmatter":{},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 24 章 其他用法补充：WorkBuddy 实操案例集/index.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 24 章 其他用法补充：WorkBuddy 实操案例集/index.md","lastUpdated":1786083382000}'),r={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 24 章 其他用法补充：WorkBuddy 实操案例集/index.md"};function o(h,a,c,E,A,u){const s=i("MermaidDiagram");return e(),p("div",null,[a[0]||(a[0]=t('<h1 id="第-24-章-备份、校验与恢复演练" tabindex="-1">第 24 章 备份、校验与恢复演练 <a class="header-anchor" href="#第-24-章-备份、校验与恢复演练" aria-label="Permalink to &quot;第 24 章 备份、校验与恢复演练&quot;">​</a></h1><p>备份的价值由恢复结果决定。看到“复制完成”或“同步成功”只能说明流程执行过；只有校验通过，并且资产已经在新的空目录中恢复且能够继续使用，才能证明恢复链路有效。</p><p>本章提供通用治理方法，不指定公司正式存储系统、保留周期或恢复责任。具体位置、权限、保密要求和恢复目标应由信息化、安全、业务和资料责任人共同确认。</p><h2 id="需要保护哪些-ai-协作资产" tabindex="-1">需要保护哪些 AI 协作资产 <a class="header-anchor" href="#需要保护哪些-ai-协作资产" aria-label="Permalink to &quot;需要保护哪些 AI 协作资产&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资产类别</th><th>建议纳入范围</th><th>恢复后检查什么</th></tr></thead><tbody><tr><td>成果资产</td><td>正式文件、项目数据、代码、图片及验收记录</td><td>文件可打开，数量、版本和关键内容一致</td></tr><tr><td>协作资产</td><td>任务规则、模板、Skill、已确认记忆和维护说明</td><td>Agent 能读取正确版本，规则和来源关系完整</td></tr><tr><td>连续性资产</td><td>快照、文件清单、校验结果、恢复说明和演练记录</td><td>能找到可用时间点，恢复步骤和责任人清楚</td></tr></tbody></table><p>密钥、Token、密码、私钥、个人账号文件、缓存和原始会话记录默认排除。确需备份的敏感配置应使用公司批准的凭证管理和加密方案，不得混入普通协作资产包。</p><h2 id="备份、同步和恢复分别解决什么" tabindex="-1">备份、同步和恢复分别解决什么 <a class="header-anchor" href="#备份、同步和恢复分别解决什么" aria-label="Permalink to &quot;备份、同步和恢复分别解决什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>主要作用</th><th>需要注意的限制</th></tr></thead><tbody><tr><td>工作目录</td><td>保存当前正在使用的最新状态</td><td>误删、误改会立即影响正式资产</td></tr><tr><td>同步</td><td>在设备或服务之间保持接近一致的状态</td><td>删除和错误也可能被同步传播</td></tr><tr><td>时间点快照</td><td>保留多个独立历史状态</td><td>同盘快照无法应对整块磁盘损坏</td></tr><tr><td>异地副本</td><td>应对设备、磁盘或单一位置不可用</td><td>必须使用公司批准的位置和访问权限</td></tr><tr><td>恢复演练</td><td>证明快照完整、步骤可执行、工作能够接续</td><td>应恢复到新位置并记录验收结果</td></tr></tbody></table><p>一个可靠方案通常同时保留当前工作目录、多个独立时间点和经过批准的第二位置，并定期做恢复演练。</p><h2 id="六步闭环" tabindex="-1">六步闭环 <a class="header-anchor" href="#六步闭环" aria-label="Permalink to &quot;六步闭环&quot;">​</a></h2><h3 id="_1-建立资产与责任清单" tabindex="-1">1. 建立资产与责任清单 <a class="header-anchor" href="#_1-建立资产与责任清单" aria-label="Permalink to &quot;1. 建立资产与责任清单&quot;">​</a></h3><p>列出需要保护的目录、文件类型、负责人、敏感级别、更新频率、允许存放的位置和恢复优先级。没有明确来源或无权保存的材料不得擅自纳入。</p><h3 id="_2-生成独立时间点快照" tabindex="-1">2. 生成独立时间点快照 <a class="header-anchor" href="#_2-生成独立时间点快照" aria-label="Permalink to &quot;2. 生成独立时间点快照&quot;">​</a></h3><p>快照放在工作目录之外，使用日期和批次形成独立目录。生成时记录成功、跳过、排除和失败项；重复运行不能静默覆盖已有快照。</p><h3 id="_3-生成并检查校验清单" tabindex="-1">3. 生成并检查校验清单 <a class="header-anchor" href="#_3-生成并检查校验清单" aria-label="Permalink to &quot;3. 生成并检查校验清单&quot;">​</a></h3><p>为快照生成文件路径、数量、大小和哈希等校验信息。校验要能发现缺失、损坏和意外新增的敏感文件。看到脚本退出成功仍需检查清单和日志。</p><h3 id="_4-管理保留周期和第二位置" tabindex="-1">4. 管理保留周期和第二位置 <a class="header-anchor" href="#_4-管理保留周期和第二位置" aria-label="Permalink to &quot;4. 管理保留周期和第二位置&quot;">​</a></h3><p>根据资产变化频率和恢复目标保留多个时间点。需要应对磁盘、设备或办公地点故障时，将快照复制到公司批准的第二介质或异地存储；不得自行上传到个人云盘或未批准服务。</p><h3 id="_5-恢复到新的空目录" tabindex="-1">5. 恢复到新的空目录 <a class="header-anchor" href="#_5-恢复到新的空目录" aria-label="Permalink to &quot;5. 恢复到新的空目录&quot;">​</a></h3><p>选择一个已校验快照，恢复到不包含现有文件的目标目录。演练阶段不覆盖正式工作区，也不直接写回 Agent 的用户级配置。</p><h3 id="_6-验收并留下演练记录" tabindex="-1">6. 验收并留下演练记录 <a class="header-anchor" href="#_6-验收并留下演练记录" aria-label="Permalink to &quot;6. 验收并留下演练记录&quot;">​</a></h3><p>至少完成以下检查：</p><ul><li>资产目录和必需文件完整，文件数量与校验清单一致。</li><li>抽样文件可以打开，关键数据、版本和引用关系正确。</li><li>至少一个模板或 Skill 能被读取并完成脱敏测试任务。</li><li>已确认记忆、来源、状态和适用范围能够继续查询。</li><li>Agent 可以根据恢复后的规则接续一个测试任务。</li><li>演练日期、快照时间、执行人、验收人、问题和修正措施已经记录。</li></ul><h2 id="恢复演练流程" tabindex="-1">恢复演练流程 <a class="header-anchor" href="#恢复演练流程" aria-label="Permalink to &quot;恢复演练流程&quot;">​</a></h2>',24)),n(s,{graph:"flowchart%20LR%0A%20%20%20%20A%5B%E9%80%89%E6%8B%A9%E5%8F%AF%E4%BF%A1%E5%BF%AB%E7%85%A7%5D%20--%3E%20B%5B%E6%A0%B8%E5%AF%B9%E6%B8%85%E5%8D%95%E4%B8%8E%E6%A0%A1%E9%AA%8C%E5%80%BC%5D%0A%20%20%20%20B%20--%3E%20C%7B%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%3F%7D%0A%20%20%20%20C%20--%20%E5%90%A6%20--%3E%20D%5B%E5%81%9C%E6%AD%A2%E5%B9%B6%E6%8A%A5%E5%91%8A%E7%BC%BA%E5%A4%B1%E6%88%96%E6%8D%9F%E5%9D%8F%5D%0A%20%20%20%20C%20--%20%E6%98%AF%20--%3E%20E%5B%E6%81%A2%E5%A4%8D%E5%88%B0%E6%96%B0%E7%9A%84%E7%A9%BA%E7%9B%AE%E5%BD%95%5D%0A%20%20%20%20E%20--%3E%20F%5B%E6%A3%80%E6%9F%A5%E6%96%87%E4%BB%B6%E3%80%81Skill%E3%80%81%E8%AE%B0%E5%BF%86%E4%B8%8E%E4%BB%BB%E5%8A%A1%E6%8E%A5%E7%BB%AD%5D%0A%20%20%20%20F%20--%3E%20G%7B%E9%AA%8C%E6%94%B6%E9%80%9A%E8%BF%87%3F%7D%0A%20%20%20%20G%20--%20%E5%90%A6%20--%3E%20H%5B%E8%AE%B0%E5%BD%95%E9%97%AE%E9%A2%98%E5%B9%B6%E4%BF%AE%E6%AD%A3%E5%A4%87%E4%BB%BD%E6%96%B9%E6%A1%88%5D%0A%20%20%20%20G%20--%20%E6%98%AF%20--%3E%20I%5B%E5%BD%92%E6%A1%A3%E6%BC%94%E7%BB%83%E8%AE%B0%E5%BD%95%E5%92%8C%E5%8F%AF%E7%94%A8%E6%81%A2%E5%A4%8D%E7%82%B9%5D%0A"}),a[1]||(a[1]=t(`<h2 id="合成示例-一份项目资料的恢复演练" tabindex="-1">合成示例：一份项目资料的恢复演练 <a class="header-anchor" href="#合成示例-一份项目资料的恢复演练" aria-label="Permalink to &quot;合成示例：一份项目资料的恢复演练&quot;">​</a></h2><p>某测试项目包含 20 份文档、1 份任务规则和 1 份校验清单。执行人先确认快照中不含凭证和个人信息，再将它恢复到一个新建的空目录。验收人核对文件数量和校验值，抽样打开文档，并使用恢复后的任务规则完成一次脱敏测试。只有数量、校验值、抽样文件和测试任务全部通过，该快照才被记录为可用恢复点。</p><h2 id="可复制恢复演练模板" tabindex="-1">可复制恢复演练模板 <a class="header-anchor" href="#可复制恢复演练模板" aria-label="Permalink to &quot;可复制恢复演练模板&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请对这份 AI 协作资产快照执行只读校验和恢复演练。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>快照位置：{位置}</span></span>
<span class="line"><span>恢复目标：{必须为空的新目录}</span></span>
<span class="line"><span>资产责任人：{责任人}</span></span>
<span class="line"><span>本次验收人：{验收人}</span></span>
<span class="line"><span>允许读取范围：{范围}</span></span>
<span class="line"><span>禁止写入范围：{正式目录、用户级配置、外部系统等}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按以下步骤执行：</span></span>
<span class="line"><span>1. 检查快照目录、文件数量、校验清单和日志；</span></span>
<span class="line"><span>2. 发现缺失、损坏、敏感文件或路径异常时立即停止；</span></span>
<span class="line"><span>3. 校验通过后恢复到指定空目录，不覆盖现有目录；</span></span>
<span class="line"><span>4. 检查必需文件，并抽样打开成果文件；</span></span>
<span class="line"><span>5. 检查一个模板或 Skill、已确认记忆及其来源关系；</span></span>
<span class="line"><span>6. 使用恢复目录完成一个脱敏测试任务；</span></span>
<span class="line"><span>7. 输出演练结果、问题清单、可用恢复点和修正建议。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>没有责任人确认，不替换正式目录，不恢复账号凭证，不重新开启自动化。</span></span></code></pre></div><h2 id="发生事故后的恢复顺序" tabindex="-1">发生事故后的恢复顺序 <a class="header-anchor" href="#发生事故后的恢复顺序" aria-label="Permalink to &quot;发生事故后的恢复顺序&quot;">​</a></h2><ol><li>停止仍在运行的 Agent、脚本、同步和自动重试。</li><li>保护现场日志、受影响目录和时间信息，避免继续写入。</li><li>确认最近一个未受影响且校验通过的快照。</li><li>在新的空目录恢复并完成验收。</li><li>由责任人确认业务影响、丢失范围和正式恢复方案。</li><li>替换正式资产前再次建立当前现场副本，保留调查和回退能力。</li><li>恢复完成后收回临时权限，修正触发条件、备份范围或处置流程。</li></ol><h2 id="常见弯路与安全边界" tabindex="-1">常见弯路与安全边界 <a class="header-anchor" href="#常见弯路与安全边界" aria-label="Permalink to &quot;常见弯路与安全边界&quot;">​</a></h2><ul><li>只检查备份任务显示“成功”，无法发现文件缺失、排除规则错误和快照损坏。</li><li>把同步目录当作唯一恢复来源，误删和误改可能已经传播到所有设备。</li><li>只保留最新一份副本，发现问题较晚时无法回到更早的可信状态。</li><li>在正式目录上直接测试恢复，会覆盖现场并扩大影响。恢复演练必须使用空目录。</li><li>未检查敏感文件排除结果，可能把凭证和个人信息复制到更广范围。</li><li>备份位置、访问权限、保留期限和销毁方式必须符合公司制度和第三方材料授权。</li></ul><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ul><li>快照包含经过确认的资产范围，并有清单、校验值和运行日志。</li><li>至少保留多个可识别时间点，第二位置符合公司批准范围。</li><li>恢复操作在空目录完成，没有覆盖正式资产和用户级配置。</li><li>文件、Skill、记忆和测试任务均通过验收。</li><li>演练记录能够说明使用了哪个快照、发现了什么问题、由谁确认和怎样修正。</li></ul><hr><h2 id="实操案例-把销售数据生成可交互-html-可视化看板" tabindex="-1">实操案例：把销售数据生成可交互 HTML 可视化看板 <a class="header-anchor" href="#实操案例-把销售数据生成可交互-html-可视化看板" aria-label="Permalink to &quot;实操案例：把销售数据生成可交互 HTML 可视化看板&quot;">​</a></h2><p>本节只解决一个问题：已经把数据整理干净、口径确认之后，怎样让 WorkBuddy 生成一个可交互 HTML 看板和对比分析报告，并保留“先检查—再确认—后执行—再核对”的控制链。</p><p>适用情境：月度或季度销售汇报需要同时交付数据明细、趋势图、对比分析和可落地建议。读者按本节做完后，会得到一个 HTML 看板文件、一份对比分析报告和一条可追溯的核对说明。</p><div class="warning custom-block"><p class="custom-block-title">先记住一条</p><ul><li>不要把原数据表交给 AI 直接覆盖；先复制一份到独立工作目录。</li><li>个人信息、客户名单、未公开经营数据不得外传；进入 HTML 看板前先做脱敏。</li><li>产品入口随版本变化，下列“日常办公 → 数据分析及可视化”“专家板块 → 数据分析师”仅为路径示例，以当前客户端为准。</li></ul></div><h3 id="_30-秒看懂本节" tabindex="-1">30 秒看懂本节 <a class="header-anchor" href="#_30-秒看懂本节" aria-label="Permalink to &quot;30 秒看懂本节&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你的目标</th><th>复制哪段提示词</th><th>得到什么</th></tr></thead><tbody><tr><td>先看数据是否可用</td><td>提示词 1：数据体检</td><td>字段、行数、异常清单和拟展示维度</td></tr><tr><td>生成可交互看板</td><td>提示词 2：HTML 看板生成</td><td>HTML 看板 + 元信息表 + 异常保留说明</td></tr><tr><td>同时做对比分析</td><td>提示词 3：对比分析扩展</td><td>环比、Top5/Bottom5、改进建议与限制说明</td></tr></tbody></table><p>第一次跟做只要六步：</p>`,18)),n(s,{graph:"flowchart%20LR%0A%20%20%20%20A%5B%E5%87%86%E5%A4%87%E5%90%88%E6%88%90%E6%A0%B7%E4%BE%8B%E8%A1%A8%5D%20--%3E%20B%5B%E5%A4%8D%E5%88%B6%E5%88%B0%E7%8B%AC%E7%AB%8B%E5%B7%A5%E4%BD%9C%E7%9B%AE%E5%BD%95%5D%0A%20%20%20%20B%20--%3E%20C%5BWorkBuddy%20%E9%80%89%E6%8B%A9%E8%AF%A5%E7%9B%AE%E5%BD%95%5D%0A%20%20%20%20C%20--%3E%20D%5B%E6%8F%90%E7%A4%BA%E8%AF%8D%201%20%E5%8F%AA%E8%AF%BB%E4%BD%93%E6%A3%80%5D%0A%20%20%20%20D%20--%3E%20E%5B%E7%A1%AE%E8%AE%A4%E7%BB%B4%E5%BA%A6%E5%92%8C%E5%8F%A3%E5%BE%84%5D%0A%20%20%20%20E%20--%3E%20F%5B%E6%8F%90%E7%A4%BA%E8%AF%8D%202%20%E7%94%9F%E6%88%90%E7%9C%8B%E6%9D%BF%5D%0A%20%20%20%20F%20--%3E%20G%5B%E6%8C%89%E9%AA%8C%E6%94%B6%E8%A1%A8%E6%A0%B8%E5%AF%B9%5D%0A"}),a[2]||(a[2]=t(`<h3 id="开始前准备" tabindex="-1">开始前准备 <a class="header-anchor" href="#开始前准备" aria-label="Permalink to &quot;开始前准备&quot;">​</a></h3><ol><li>新建一个文件夹，例如 <code>第24章-可视化看板练习</code>。</li><li>准备一份合成的销售样例表 <code>synthetic-monthly-sales.csv</code>，至少包含：日期、区域、产品、销售额、订单数。本节示例数据全部为合成数据，请勿直接套用真实经营数据。</li><li>在 WorkBuddy 中选择该目录作为工作空间；可用入口如“日常办公 → 数据分析及可视化”或“专家板块 → 数据分析师”，以当前客户端为准。</li></ol><p>合成样例示意（仅供参考字段结构，不作为业务事实）：</p><table tabindex="0"><thead><tr><th>日期</th><th>区域</th><th>产品</th><th style="text-align:right;">销售额</th><th style="text-align:right;">订单数</th></tr></thead><tbody><tr><td>2026-07-01</td><td>华北</td><td>产品 A</td><td style="text-align:right;">1280</td><td style="text-align:right;">12</td></tr><tr><td>2026-07-02</td><td>华东</td><td>产品 B</td><td style="text-align:right;">980</td><td style="text-align:right;">9</td></tr><tr><td>2026-07-03</td><td>华南</td><td>产品 A</td><td style="text-align:right;">1560</td><td style="text-align:right;">15</td></tr><tr><td>2026-07-04</td><td>华中</td><td>产品 C</td><td style="text-align:right;">760</td><td style="text-align:right;">7</td></tr><tr><td>2026-07-05</td><td>华北</td><td>产品 B</td><td style="text-align:right;">-320</td><td style="text-align:right;">-3</td></tr></tbody></table><p>第五行故意放入负数（退货冲正），用于验证异常不会被偷偷删除或隐藏。</p><h3 id="步骤一-数据体检-不直接画图" tabindex="-1">步骤一：数据体检，不直接画图 <a class="header-anchor" href="#步骤一-数据体检-不直接画图" aria-label="Permalink to &quot;步骤一：数据体检，不直接画图&quot;">​</a></h3><p><strong>复制提示词 1：数据体检</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请只读检查工作目录中的 synthetic-monthly-sales.csv，先不要生成任何图表或看板。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请报告：</span></span>
<span class="line"><span>1. 字段名、记录数、空值和重复行；</span></span>
<span class="line"><span>2. 数值列的最小值、最大值、合计与负值出现位置；</span></span>
<span class="line"><span>3. 日期范围与是否存在跨期记录；</span></span>
<span class="line"><span>4. 分类字段的取值与各自样本量；</span></span>
<span class="line"><span>5. 可用于展示的维度与指标组合；</span></span>
<span class="line"><span>6. 拟生成的看板草图与可能涉及的口径问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>已知条件：本表为 2026 年 7 月的合成销售数据。</span></span>
<span class="line"><span>等我确认维度、口径和异常处理后，再生成看板。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">人工确认点</p><ul><li>区域、产品、时间维度是否就是这次汇报要展示的维度。</li><li>负数是否为退货冲正，是否要在看板中单独标注。</li><li>时间按日、按周还是按月聚合。</li><li>单位是否需要从“元”换算为“万元”。</li></ul></div><h3 id="步骤二-生成可交互-html-看板" tabindex="-1">步骤二：生成可交互 HTML 看板 <a class="header-anchor" href="#步骤二-生成可交互-html-看板" aria-label="Permalink to &quot;步骤二：生成可交互 HTML 看板&quot;">​</a></h3><p>只有当数据体检报告中的字段、行数、异常位置和拟展示维度都核对无误后，才复制下一段提示词。</p><p><strong>复制提示词 2：HTML 看板生成</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于已确认的体检结果生成一份可交互 HTML 看板，保存为 sales-dashboard.html。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 看板包含：销售趋势折线图、区域占比饼图、产品销售额 Top5 柱状图；</span></span>
<span class="line"><span>2. 支持按区域、产品筛选，筛选切换时所有图表同步更新；</span></span>
<span class="line"><span>3. 每张图写明：标题、单位、时间范围、样本量和数据更新时间；</span></span>
<span class="line"><span>4. 负数（退货冲正）不得隐藏；在趋势图和 Top5 中单独显示，并在图例标注“退货冲正”；</span></span>
<span class="line"><span>5. 不展示未在数据中出现的分类；缺失值显示为“无数据”，不补零；</span></span>
<span class="line"><span>6. 同步生成 dashboard-meta.md：列出数据来源文件、行数、字段、图表清单、异常处理说明和原文件路径。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要修改原 csv 文件。生成完成后请报告：生成的文件名、图表数量、异常保留情况和总销售额。</span></span></code></pre></div><p><img src="`+d+`" alt="合成示例：WorkBuddy 从提示词到可交互 HTML 看板的生成流程演示" loading="lazy"></p><p><em>图 24-1　合成示例：演示循环展示&quot;输入提示词 → 数据体检 → 生成看板 → 筛选交互&quot;四阶段；负值（退货冲正 -320 元）在趋势图、占比图、柱状图中均单独标注，不得隐藏。原始数据 5 行均为合成，不构成对原文事实的延伸。</em></p><div class="tip custom-block"><p class="custom-block-title">验收只看四点</p><ol><li>浏览器打开 HTML 后，筛选可正常切换并同步刷新所有图表；</li><li>每张图都标注了标题、单位、时间范围、样本量和更新时间；</li><li>负数或退货冲正没有被“漂亮化”掉；</li><li>原 csv 文件未被修改，dashboard-meta.md 能追溯到来源。</li></ol></div><h3 id="步骤三-扩展到对比分析" tabindex="-1">步骤三：扩展到对比分析 <a class="header-anchor" href="#步骤三-扩展到对比分析" aria-label="Permalink to &quot;步骤三：扩展到对比分析&quot;">​</a></h3><p>如果汇报同时需要环比、Top5/Bottom5 和改进建议，在前一步结果通过验收后再使用下一段提示词。它要求每条结论绑定具体指标，并明确区分“基于数据的结论”与“建议”。</p><p><strong>复制提示词 3：对比分析扩展</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基于已确认无误的销售数据生成对比分析报告 comparison-report.md。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请完成：</span></span>
<span class="line"><span>1. 计算环比增长率，并标出负增长的记录；</span></span>
<span class="line"><span>2. 计算各区域、各产品的销售额占比；同比需注明是否使用了同期对照数据，未提供同期数据时只做环比并明确说明；</span></span>
<span class="line"><span>3. 输出 Top5 和 Bottom5 排名表；</span></span>
<span class="line"><span>4. 给出 3 条可落地改进建议，每条建议引用至少一个具体指标作为依据；</span></span>
<span class="line"><span>5. 明确标注哪些是“基于数据的结论”，哪些是“建议”；建议不得暗示已被经营层采纳；</span></span>
<span class="line"><span>6. 列出缺失值、小样本、未匹配和待确认事项，不得用相关性推断因果。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>同步输出 comparison-meta.md：列出输入文件、行数、计算口径、异常处理和差异说明。</span></span>
<span class="line"><span>不要覆盖原文件，不要外发，不要发布到外部平台。</span></span></code></pre></div><h3 id="步骤四-修正闭环" tabindex="-1">步骤四：修正闭环 <a class="header-anchor" href="#步骤四-修正闭环" aria-label="Permalink to &quot;步骤四：修正闭环&quot;">​</a></h3><p>如果生成的看板或报告出现下列任一情况，不要手工改完就结束，要让 WorkBuddy 按修正后的规则重新生成：</p><ul><li>模型擅自删除了负值或异常行；</li><li>图表缺少单位、时间范围或样本量；</li><li>结论没有引用具体指标；</li><li>同比/环比计算口径未声明。</li></ul><p><strong>复制提示词 4：发现错误后修正</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请不要直接改一处就结束。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先说明本次输出存在哪些问题；</span></span>
<span class="line"><span>把修正规则补充到规则清单；</span></span>
<span class="line"><span>再重新生成 sales-dashboard-v2.html 和 comparison-report-v2.md；</span></span>
<span class="line"><span>最后重新报告：图表数量、异常保留情况、总销售额、Top5/Bottom5 与上一版的差异。</span></span></code></pre></div><h3 id="换成自己的文件时-只改这几处" tabindex="-1">换成自己的文件时，只改这几处 <a class="header-anchor" href="#换成自己的文件时-只改这几处" aria-label="Permalink to &quot;换成自己的文件时，只改这几处&quot;">​</a></h3><table tabindex="0"><thead><tr><th>占位内容</th><th>改成什么</th></tr></thead><tbody><tr><td><code>synthetic-monthly-sales.csv</code></td><td>你的实际文件名</td></tr><tr><td>日期、区域、产品、销售额</td><td>你的字段名</td></tr><tr><td>按区域/产品/日聚合</td><td>你确认的聚合粒度</td></tr><tr><td>单位“元”或“万元”</td><td>你确认的口径</td></tr><tr><td>Top5/Bottom5</td><td>你确认的排名范围</td></tr><tr><td>输出文件名</td><td>你希望交付的文件名</td></tr></tbody></table><p>不要删除这些句子：</p><ul><li>先检查，等我确认后再执行。</li><li>不要覆盖原文件。</li><li>无法判断的内容标记“待确认”。</li><li>输出处理前后的行数、关键金额和差异核对。</li></ul><h3 id="常见弯路" tabindex="-1">常见弯路 <a class="header-anchor" href="#常见弯路" aria-label="Permalink to &quot;常见弯路&quot;">​</a></h3><ul><li>跳过数据体检直接生成看板，导致负值被自动忽略或字段含义被猜测。</li><li>图表只看美观不核对元信息，单位、时间范围或样本量缺失。</li><li>同比未声明是否使用同期对照数据，导致读者误以为是同期可比。</li><li>把“销售额和广告投入相关”直接写成“广告投入提升了销售额”。</li><li>把改进建议写成已被公司采纳的结论。</li></ul><h3 id="人工确认点" tabindex="-1">人工确认点 <a class="header-anchor" href="#人工确认点" aria-label="Permalink to &quot;人工确认点&quot;">​</a></h3><ul><li>输入材料是否合法、完整、允许用于本次处理，是否包含个人信息或未公开经营数据。</li><li>展示维度、聚合粒度、单位、口径是否符合汇报要求。</li><li>负数、退货、跨期、未匹配等异常如何呈现。</li><li>看板是否需要外发；如需外发，使用公司批准的渠道并脱敏。</li><li>改进建议是否仅作为参考，而非作为经营事实或财务结论。</li></ul><h3 id="安全边界" tabindex="-1">安全边界 <a class="header-anchor" href="#安全边界" aria-label="Permalink to &quot;安全边界&quot;">​</a></h3><ul><li>不向未批准的外部服务上传敏感表格、个人信息和未公开经营数据。</li><li>不把模型推断当作业务事实、财务结论或管理决定。</li><li>不自动覆盖源文件、不自动外发、不自动发布或提交审批。</li><li>对小样本、自由文本和联系方式做脱敏或限制访问。</li><li>产品入口、界面和能力可能随版本变化，以当前客户端和官方说明为准。</li></ul><h3 id="参考资料与改编说明" tabindex="-1">参考资料与改编说明 <a class="header-anchor" href="#参考资料与改编说明" aria-label="Permalink to &quot;参考资料与改编说明&quot;">​</a></h3><p>本节方法内核改编自一篇公开微信文章：秋叶 AIExcel，《太强了！WorkBuddy 轻松实现数据可视化，3 分钟搞定 3 小时工作！》，2026-07-27。原文以宣传口径列举数据清洗、多表合并、HTML 看板和对比分析四类用法；本节只保留其中“可交互 HTML 看板”与“对比分析”两个真正新增的能力，按蓝皮书第 17 章派生标准改写为“先检查—再确认—后执行—再核对”的两阶段任务链。原文中“3 分钟搞定”“免费积分够用”等宣传话术、具体技能名清单、产品入口细节、价格和版权图片均未进入正文；所有示例数据、字段、区域、产品名称均为合成，不构成对原文事实的延伸。</p><ul><li>原文链接：<a href="https://mp.weixin.qq.com/s/ljJ_2Xran76fKk5XEHtroA" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/ljJ_2Xran76fKk5XEHtroA</a></li><li>来源名称：秋叶 AIExcel（公众号）</li><li>访问日期：2026-07-27</li><li>改编范围：方法重构、合成示例、提示词重新设计、保留控制链。</li></ul>`,38))])}const m=l(r,[["render",o]]);export{B as __pageData,m as default};
